#ifndef MRKENDDO_SD_WEB_UI_H_
#define MRKENDDO_SD_WEB_UI_H_

namespace mrkenddo::web_ui {
inline constexpr char kStorageHtml[] = R"SDUI(<!doctype html>
<html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>microSD · MrKenDDo Robot</title><style>
:root{color-scheme:dark;font:15px/1.55 system-ui;background:#08111f;color:#edf5ff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(at top left,#183a53,#08111f 60%);min-height:100vh}main{max-width:1000px;margin:auto;padding:24px}a{color:#69b7ff}h1{margin:10px 0}header{display:flex;justify-content:space-between;align-items:center;gap:16px}.tag{font-size:12px;color:#52e2bc;letter-spacing:.12em}.panel{margin-top:20px;background:#102137;border:1px solid #2b405a;border-radius:20px;padding:20px}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}button,.button{background:#203b56;border:1px solid #375775;border-radius:10px;padding:10px 14px;color:inherit;cursor:pointer;text-decoration:none;font:inherit}button.primary{background:#31d4aa;color:#06201d;border:0;font-weight:700}button.danger{color:#ff9aa6}button:disabled{opacity:.5;cursor:wait}p,small{color:#a6bad0}.path{overflow-wrap:anywhere;font-family:monospace;margin:16px 0}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px 6px;text-align:left;border-bottom:1px solid #293d53}th{font-size:12px;color:#a6bad0}td:first-child{word-break:break-word}td:last-child{min-width:160px}.name{background:none;border:0;padding:0;text-align:left;color:#a6dcff}.notice{min-height:24px;margin-top:14px;white-space:pre-wrap;overflow-wrap:anywhere}.error{color:#ff9aa6}progress{width:100%;height:14px;accent-color:#31d4aa}input[type=file]{max-width:100%;margin:8px 0}.stats{display:flex;gap:24px;flex-wrap:wrap}.stats strong{display:block;font-size:20px}footer{margin:24px 0;font-size:12px;color:#91a8c0}@media(max-width:600px){main{padding:14px}.panel{padding:14px}h1{font-size:23px}header{align-items:flex-start}button,.button{padding:8px 10px;font-size:13px}}
</style></head><body><main><header><div><div class="tag">MRKENDDO ROBOT · LOCAL STORAGE</div><h1>Thẻ nhớ microSD</h1></div><a class="button" href="/">← Điều khiển robot</a></header>
<section class="panel"><div class="stats"><div><small>Trạng thái</small><strong id="state">Đang kiểm tra…</strong></div><div><small>Tổng dung lượng</small><strong id="total">—</strong></div><div><small>Còn trống</small><strong id="free">—</strong></div></div><p id="detail"></p><div class="row"><button data-action onclick="operation('mount')">Kết nối lại</button><button data-action onclick="operation('refresh')">Cập nhật dung lượng</button><button data-action onclick="operation('unmount')">Tháo thẻ an toàn</button><button data-action onclick="reload()">Làm mới</button></div></section>
<section class="panel"><div class="row"><button data-action onclick="openDirectory('/')">Thư mục gốc</button><button data-action onclick="up()">↑ Thư mục cha</button><button data-action onclick="mkdir()">+ Tạo thư mục</button><button class="danger" onclick="stopPlayback()">Dừng phát</button></div><p>Phát offline hiện hỗ trợ MP3 và Ogg/Opus (.mp3, .ogg, .opus); file được giải mã bằng pipeline âm thanh hiện có trên robot.</p><div id="path" class="path">/</div><div class="table-wrap"><table><thead><tr><th>Tên file / thư mục</th><th>Dung lượng</th><th>Thao tác</th></tr></thead><tbody id="files"></tbody></table></div><div class="row" style="margin-top:14px"><button id="previous" data-action onclick="page(-1)">← Trang trước</button><button id="next" data-action onclick="page(1)">Trang tiếp →</button></div></section>
<section class="panel"><h2>Tải file lên thẻ</h2><p>File thường tối đa 1 GiB. Ảnh đầu vào tối đa 5 MiB sẽ được trình duyệt tự xoay đúng chiều, thu vừa cạnh dài 480 px và nén thành JPEG tối đa 512 KiB trước khi tải lên. File trùng tên sẽ bị từ chối; bạn có thể đổi tên hoặc chủ động xóa file cũ. Đường dẫn và tên file hỗ trợ tiếng Việt.</p><input id="input" data-action type="file" multiple><div class="row"><button class="primary" data-action onclick="upload()">Tải lên thư mục hiện tại</button><button class="danger" id="cancel" onclick="cancelUpload()">Hủy upload dang dở</button></div><progress id="progress" max="100" value="0"></progress><div id="message" class="notice" role="status"></div></section>
<footer>Dùng trong LAN tin cậy. Chờ xác nhận “Đã ngắt kết nối” trước khi tháo thẻ. File tạm upload không hoàn tất được ẩn khỏi danh sách; chức năng Hủy upload hoặc Tháo thẻ an toàn sẽ dọn file tạm của phiên hiện tại. Firmware không tự format thẻ.</footer></main>
<script>
const $=id=>document.getElementById(id);let current='/',offset=0,hasMore=false,busy=false,cancelled=false,activePath='',serverUpload='',maxFileBytes=1073741824,chunkBytes=1048576;
const sizes=n=>n>=1073741824?(n/1073741824).toFixed(2)+' GiB':n>=1048576?(n/1048576).toFixed(1)+' MiB':n>=1024?(n/1024).toFixed(1)+' KiB':n+' B';
const url=(op,path=current,extra={})=>'/api/storage?'+new URLSearchParams({op,path,...extra});
const message=(text,error=false)=>{$('message').textContent=text;$('message').className='notice'+(error?' error':'')};
function lock(value){busy=value;document.querySelectorAll('[data-action]').forEach(x=>x.disabled=value);$('cancel').disabled=false}
async function api(address,options={}){for(let attempt=0;;attempt++){const r=await fetch(address,options);const data=await r.json();if(r.status===503&&attempt<3){await new Promise(resolve=>setTimeout(resolve,100*(attempt+1)));continue}if(!r.ok)throw Error(data.error||'HTTP '+r.status);return data}}
async function status(){const d=await api(url('status'));const labels={mounted:'Đã kết nối',mounting:'Đang kết nối…',unmounted:'Đã ngắt kết nối',error:'Không đọc được thẻ'};$('state').textContent=labels[d.state]||d.state;$('detail').textContent=d.message;$('total').textContent=d.total_bytes?sizes(d.total_bytes):'—';$('free').textContent=d.space_valid?sizes(d.free_bytes):'Chưa cập nhật';serverUpload=d.upload_path||'';maxFileBytes=d.max_file_bytes||maxFileBytes;chunkBytes=d.chunk_bytes||chunkBytes;return d}
const join=name=>(current==='/'?'':current)+'/'+name;
const imageInputMaxBytes=5*1024*1024,imageOutputMaxBytes=512*1024,imageMaxEdge=480;
const isImageFile=file=>file.type.startsWith('image/')||/\.(jpe?g|png|webp|gif|bmp|avif)$/i.test(file.name);
const canvasJpeg=(canvas,quality)=>new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('Trình duyệt không tạo được ảnh JPEG.')),'image/jpeg',quality));
async function decodeUploadImage(file){
  if(window.createImageBitmap){try{return await createImageBitmap(file)}catch(_){}}
  const objectUrl=URL.createObjectURL(file);
  try{return await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('Trình duyệt không đọc được ảnh này. Hãy thử JPEG, PNG hoặc WebP.'));image.src=objectUrl})}
  finally{URL.revokeObjectURL(objectUrl)}
}
async function optimizeImage(file){
  if(!isImageFile(file))return file;
  if(file.size>imageInputMaxBytes)throw Error('Ảnh '+file.name+' vượt giới hạn đầu vào 5 MiB.');
  const source=await decodeUploadImage(file),sourceWidth=source.width||source.naturalWidth,sourceHeight=source.height||source.naturalHeight;
  if(!sourceWidth||!sourceHeight)throw Error('Không xác định được kích thước ảnh '+file.name+'.');
  const canvas=document.createElement('canvas'),context=canvas.getContext('2d');
  if(!context){if(source.close)source.close();throw Error('Trình duyệt không hỗ trợ xử lý ảnh trên thiết bị.')}
  const qualities=[0.88,0.82,0.76,0.70,0.64,0.58];let edge=imageMaxEdge,blob=null;
  try{
    while(edge>=160){
      const scale=Math.min(1,edge/Math.max(sourceWidth,sourceHeight));
      canvas.width=Math.max(1,Math.round(sourceWidth*scale));canvas.height=Math.max(1,Math.round(sourceHeight*scale));
      context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(source,0,0,canvas.width,canvas.height);
      for(const quality of qualities){blob=await canvasJpeg(canvas,quality);if(blob.size<=imageOutputMaxBytes){
        const name=file.name.replace(/\.[^.]*$/,'')+'.jpg';
        return new File([blob],name,{type:'image/jpeg',lastModified:file.lastModified});
      }}
      edge=Math.floor(edge*0.8);
    }
    throw Error('Không thể nén ảnh xuống dưới 512 KiB; hãy chọn ảnh nhỏ hơn.');
  }finally{canvas.width=canvas.height=0;if(source.close)source.close()}
}
async function list(){const d=await api(url('list',current,{offset}));hasMore=d.more;$('path').textContent=current;$('files').replaceChildren();for(const item of d.entries){const tr=document.createElement('tr'),name=document.createElement('td'),size=document.createElement('td'),actions=document.createElement('td');const label=document.createElement(item.directory?'button':'span');label.textContent=(item.directory?'📁 ':'')+item.name;if(item.directory){label.className='name';label.onclick=()=>openDirectory(join(item.name))}name.append(label);size.textContent=item.directory?'-':sizes(item.size);if(!item.directory){if(/\.(mp3|ogg|opus)$/i.test(item.name)){const play=document.createElement('button');play.textContent='▶ Phát';play.onclick=()=>playItem(join(item.name));actions.append(play)}if(/\.(jpe?g)$/i.test(item.name)){const view=document.createElement('button');view.textContent='▣ Xem TFT';view.onclick=()=>showItem(join(item.name));actions.append(view)}const download=document.createElement('a');download.className='button';download.textContent='Tải về';download.href='/api/storage/download?'+new URLSearchParams({path:join(item.name)});actions.append(download)}const remove=document.createElement('button');remove.textContent='Xóa';remove.className='danger';remove.onclick=()=>removeItem(item.name,item.directory);actions.append(remove);tr.append(name,size,actions);$('files').append(tr)}if(!d.entries.length){const row=document.createElement('tr'),cell=document.createElement('td');cell.colSpan=3;cell.textContent='Thư mục trống';row.append(cell);$('files').append(row)}$('previous').disabled=offset===0;$('next').disabled=!hasMore}
async function showItem(path){try{const d=await api(url('show',path),{method:'POST'});message(d.message||'Đang chuyển ảnh lên TFT.')}catch(e){message(e.message,true)}}
async function playItem(path){try{const d=await api(url('play',path),{method:'POST'});message(d.message||'Đã gửi yêu cầu phát.')}catch(e){message(e.message,true)}}
async function stopPlayback(){try{const d=await api(url('stop','/'),{method:'POST'});message(d.message||'Đã gửi yêu cầu dừng.')}catch(e){message(e.message,true)}}
async function reload(){if(busy)return;try{const d=await status();if(d.state==='mounted')await list();else $('files').replaceChildren();}catch(e){message(e.message,true)}}
async function openDirectory(path){if(busy)return;const old=current;current=path;offset=0;try{await list()}catch(e){current=old;message(e.message,true)}}
function up(){if(current!=='/')openDirectory(current.substring(0,current.lastIndexOf('/'))||'/')}
async function page(direction){if(busy||direction>0&&!hasMore)return;offset=Math.max(0,offset+direction*24);try{await list()}catch(e){message(e.message,true)}}
async function operation(op){if(busy)return;lock(true);try{await api(url(op),{method:'POST'});let done=false;for(let i=0;i<40;i++){await new Promise(r=>setTimeout(r,500));const d=await status();done=op==='unmount'?d.state==='unmounted':op==='refresh'?d.space_valid:d.state==='mounted';if(done)break;if(i>2&&d.state==='error')throw Error(d.message)}message(done?'Đã hoàn tất.':'Đang xử lý thẻ, hãy bấm Làm mới sau.');}catch(e){message(e.message,true)}finally{lock(false);await reload()}}
async function mkdir(){if(busy)return;const name=prompt('Tên thư mục mới:');if(!name)return;try{await api(url('mkdir',join(name)),{method:'POST'});await reload();message('Đã tạo thư mục.')}catch(e){message(e.message,true)}}
async function removeItem(name,isDirectory){if(busy)return;const question=isDirectory?'Xóa thư mục "'+name+'" cùng toàn bộ file và thư mục bên trong? Thao tác không thể hoàn tác.':'Xóa file "'+name+'" khỏi thẻ nhớ? Thao tác không thể hoàn tác.';if(!confirm(question))return;try{lock(true);await api(url('delete',join(name)),{method:'POST'});message('Đã xóa.')}catch(e){message(e.message,true)}finally{lock(false);await reload()}}
async function cancelUpload(){cancelled=true;if(busy)return;const path=serverUpload||activePath;if(!path){message('Không có upload dang dở trong phiên này.');return}try{await api(url('abort_upload',path),{method:'POST'});activePath='';await reload();message('Đã hủy upload và xóa file tạm.')}catch(e){message(e.message,true)}}
async function upload(){if(busy)return;const files=Array.from($('input').files);if(!files.length){message('Hãy chọn file trước.');return}lock(true);cancelled=false;try{for(const file of files){if(file.size>maxFileBytes&&!isImageFile(file))throw Error('File '+file.name+' vượt giới hạn '+sizes(maxFileBytes)+'.');message(isImageFile(file)?'Đang tối ưu ảnh trên thiết bị của bạn…':'Đang chuẩn bị '+file.name+'…');const uploadFile=await optimizeImage(file);if(uploadFile.size>maxFileBytes)throw Error('File '+uploadFile.name+' vượt giới hạn '+sizes(maxFileBytes)+'.');activePath=join(uploadFile.name);let position=0;do{if(cancelled)throw Error('Đã hủy upload.');const body=uploadFile.slice(position,position+chunkBytes);await api('/api/storage/upload?'+new URLSearchParams({path:activePath,offset:position,total:uploadFile.size}),{method:'POST',headers:{'Content-Type':'application/octet-stream'},body});position+=body.size;$('progress').value=uploadFile.size?Math.round(position/uploadFile.size*100):100;message(uploadFile.name+' · '+sizes(position)+' / '+sizes(uploadFile.size)+(uploadFile!==file?' (đã tối ưu từ '+sizes(file.size)+')':''))}while(position<uploadFile.size);activePath=''}message('Đã tải xong '+files.length+' file.');$('input').value=''}catch(e){message(e.message,true);if(activePath){try{await api(url('abort_upload',activePath),{method:'POST'});activePath=''}catch(_){message(e.message+' Hãy dùng Hủy upload khi kết nối ổn định.',true)}}}finally{lock(false);await reload()}}
reload();
</script></body></html>)SDUI";
}  // namespace mrkenddo::web_ui
#endif
